const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/contracts/%7Bcontract_id%7D/invoice_configuration'
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/contracts/%7Bcontract_id%7D/invoice_configuration"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/contracts/%7Bcontract_id%7D/invoice_configuration',
  headers: {'content-type': 'application/json'},
  body: {
    invoice_configuration: {
      separate_billing_for_stored_materials: true,
      stored_materials_billing_method: 'move_new_materials',
      contract_invoicing_method: 'progressive'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/contracts/%7Bcontract_id%7D/invoice_configuration"),
    Content = new StringContent("{\"invoice_configuration\":{\"separate_billing_for_stored_materials\":true,\"stored_materials_billing_method\":\"move_new_materials\",\"contract_invoicing_method\":\"progressive\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
